int magic(int prevedge) {
    int curr = edge[prevedge].dest, vlow;
    if (v[curr]) return v[curr];
    v[curr] = vlow = ++vtop;
    for (int e = head[curr], vtmp; e; e = edge[e].next)
        if (e != (prevedge ^ 1)) {
            vtmp = magic(e);
            if (v[curr] < vtmp) be[++btop] = e;
            if (vtmp < vlow) vlow = vtmp;
        }
    return v[curr] = vlow;
}

